/// `deal.To.Length == 1 && deal.To[0] == Faction.Fremen` (`To` is never null for a real offer).
fn is_only_to_fremen(deal: &DealOffered) -> bool {
    let to = deal.to.as_ref().nre();
    to.len() == 1 && *cs::index_array(to, 0) == Faction::Fremen
}

